package com.fixmer.mared.technology.server.remote;
import com.fixmer.genesis.technology.server.remote.*;import com.fixmer.mared.Mared;
import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.*;import net.neoforged.neoforge.event.entity.player.PlayerEvent;import net.neoforged.neoforge.network.PacketDistributor;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** UUID/auth/operator state comes from the current ServerPlayer. Disk/crypto stays on the serial worker. */
@EventBusSubscriber(modid=Mared.MOD_ID)
public final class ServerAdmin75 {
 private static final Map<MinecraftServer,Actor> actors=new IdentityHashMap<>();private static final class Actor{final ExecutorService io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"genesis-admin88");t.setDaemon(true);return t;});final Map<UUID,Long> limits=new HashMap<>();boolean busy;}
 private ServerAdmin75(){}
 @SubscribeEvent public static void started(ServerStartedEvent e){if("75".equals(System.getenv("GENESIS_DEDICATED75_VERSION")))actors.put(e.getServer(),new Actor());}
 private static boolean current(ServerPlayer p,MinecraftServer s){return p.getServer()==s&&s.getPlayerList().getPlayer(p.getUUID())==p;}
 private static boolean root(ServerPlayer p){return p.createCommandSourceStack().hasPermission(4);}
 private static void reply(ServerPlayer p,UUID request,Map<String,String> data){try{PacketDistributor.sendToPlayer(p,new ServerAdminPayloads75.View(request,ControlWire73.encode(data)));}catch(Exception ignored){}}
 private static void reply88(ServerPlayer p,UUID request,Map<String,String> data){try{PacketDistributor.sendToPlayer(p,new ServerAccessPayloads88.View(request,ControlWire73.encode(data)));}catch(Exception ignored){}}
 private static String code(Exception e){String s=e.getMessage();return s!=null&&s.matches("ACCESS88_[A-Z_]{1,40}")?s:"REFUSED";}
 private static Actor begin(ServerPlayer p,MinecraftServer s){if(!current(p,s))return null;Actor a=actors.get(s);if(a==null)return null;long now=System.nanoTime(),last=a.limits.getOrDefault(p.getUUID(),0L);if(now-last<500_000_000L||a.limits.size()>=256&&!a.limits.containsKey(p.getUUID()))return null;a.limits.put(p.getUUID(),now);return a;}
 public static void receive(ServerPlayer p,ServerAdminPayloads75.Request request){MinecraftServer s=p.getServer();if(s!=null)s.execute(()->receive0(p,s,request));}
 private static void receive0(ServerPlayer p,MinecraftServer s,ServerAdminPayloads75.Request request){if(!current(p,s)||!p.connection.hasChannel(ServerAdminPayloads75.View.TYPE.id()))return;if(!actors.containsKey(s)){reply(p,request.request(),Map.of("result","NOT_MANAGED"));return;}Actor a=begin(p,s);if(a==null){reply(p,request.request(),Map.of("result","BUSY"));return;}if(a.busy){reply(p,request.request(),Map.of("result","BUSY"));return;}
  if(request.request().equals(new UUID(0,0))||!ServerAccess88.ROOT_ACTIONS.contains(request.action())||!request.label().matches("[A-Za-z0-9_-]{1,40}")){reply(p,request.request(),Map.of("result","INVALID"));return;}
  boolean operator=root(p),online=s.usesAuthentication();UUID actor=p.getUUID();long authorizedAt=System.currentTimeMillis();if(!online){reply(p,request.request(),Map.of("result","DENIED"));return;}
  a.busy=true;a.io.execute(()->{Map<String,String> response;try{
   Path path=Path.of(System.getenv("GENESIS_DEDICATED74_ROOT"));var admin=DedicatedAdmin75.open(path);var d=new TreeMap<>(admin.view());d.put("restart103",Boolean.toString(admin.supportsRestart103()));d.put("inplace104",Boolean.toString(admin.isInPlace104()));var session=DedicatedSession74.open(System.getenv());if(session==null||!d.get("generation").equals(Integer.toString(session.generation)))throw new IllegalStateException();
   if(Files.exists(path.resolve("owner88"))){var access=ServerAccess88.open(path);var rights=access.access(actor,operator,online);d.put("access88",rights.get("actions"));d.put("role88",rights.get("role"));if(!request.action().equals("PING"))access.queue(actor,operator,online,authorizedAt,request.request(),request.action(),request.label());}
   else{if(!operator)throw new IllegalStateException();if(!request.action().equals("PING"))admin.submit(request.request(),request.action(),request.label());}
   d.put("result",request.action().equals("PING")?"STATE":"QUEUED");response=d;
  }catch(Exception bad){response=Map.of("result",code(bad));}Map<String,String> value=response;s.execute(()->{if(actors.get(s)!=a)return;a.busy=false;if(current(p,s)&&s.usesAuthentication()&&(!operator||root(p)))reply(p,request.request(),value);});});
 }
 public static void access88(ServerPlayer p,ServerAccessPayloads88.Request q){MinecraftServer s=p.getServer();if(s!=null)s.execute(()->access0(p,s,q));}
 private static void access0(ServerPlayer p,MinecraftServer s,ServerAccessPayloads88.Request q){if(!current(p,s)||!p.connection.hasChannel(ServerAccessPayloads88.View.TYPE.id()))return;if(!actors.containsKey(s)){reply88(p,q.request(),Map.of("result","NOT_MANAGED"));return;}Actor a=begin(p,s);if(a==null){reply88(p,q.request(),Map.of("result","BUSY"));return;}if(a.busy){reply88(p,q.request(),Map.of("result","BUSY"));return;}if(q.request().equals(new UUID(0,0))||!Set.of("VIEW","SET").contains(q.operation())){reply88(p,q.request(),Map.of("result","INVALID"));return;}
  UUID actor=p.getUUID();boolean operator=root(p),online=s.usesAuthentication();long accepted=System.currentTimeMillis();StringBuilder roster=new StringBuilder();int shown=0;for(ServerPlayer player:s.getPlayerList().getPlayers()){if(shown++>=64)break;String name=player.getName().getString();if(name.matches("[A-Za-z0-9_]{1,16}"))roster.append(player.getUUID()).append('=').append(name).append('\n');}String players88=roster.toString();if(!online||q.operation().equals("SET")&&!operator){reply88(p,q.request(),Map.of("result","ACCESS88_DENIED"));return;}a.busy=true;
  a.io.execute(()->{Map<String,String> data;try{if(System.currentTimeMillis()-accepted>5000)throw new java.io.IOException("ACCESS88_SESSION_STALE");Path path=Path.of(System.getenv("GENESIS_DEDICATED74_ROOT"));var session=DedicatedSession74.open(System.getenv());if(session==null||!DedicatedAdmin75.open(path).view().get("generation").equals(Integer.toString(session.generation)))throw new IllegalStateException();var access=ServerAccess88.open(path);if(q.operation().equals("SET"))access.change(actor,operator,online,q.target(),q.role(),q.revision(),q.request());var out=new TreeMap<>(access.view(actor,operator,online));out.put("players",players88);out.put("result",q.operation().equals("VIEW")?"STATE":"CHANGED");data=out;}catch(Exception e){data=Map.of("result",code(e));}Map<String,String> answer=data;s.execute(()->{if(actors.get(s)!=a)return;a.busy=false;if(current(p,s)&&s.usesAuthentication()&&(!operator||root(p)))reply88(p,q.request(),answer);});});
 }
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent e){if(e.getEntity() instanceof ServerPlayer p){Actor a=actors.get(p.getServer());if(a!=null)a.limits.remove(p.getUUID());}}
 @SubscribeEvent public static void stopped(ServerStoppedEvent e){Actor a=actors.remove(e.getServer());if(a!=null)a.io.shutdownNow();}
}
